schemaSql:
-- Settings Table (USD exchange rate)
create table if not exists public.tarag4_settings (
  id uuid primary key default gen_random_uuid(),
  usd_rate numeric(12,2) not null default 3000.00,
  updated_at timestamptz default now(),
  created_at timestamptz default now()
);

-- Delivery Areas Table
create table if not exists public.tarag4_delivery_areas (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  area_type text default 'منطقة رئيسية',
  delivery_fee numeric(12,2) not null default 0.00,
  is_active boolean default true,
  created_at timestamptz default now()
);

-- Products Catalog Table
create table if not exists public.tarag4_products (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  category text not null, -- معدات طبية, مستهلكات, أجهزة مختبر
  price_usd numeric(10,2) not null default 0.00,
  stock_quantity integer not null default 0,
  image_url text,
  is_visible boolean not null default true,
  description text,
  created_at timestamptz default now()
);

-- Customers Profiles Table
create table if not exists public.tarag4_customers (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  full_name text not null,
  phone text not null,
  email text,
  address text,
  created_at timestamptz default now()
);

-- Orders Table
create table if not exists public.tarag4_orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  customer_name text not null,
  phone text not null,
  delivery_area_name text not null,
  detailed_address text not null,
  delivery_type text not null default 'delivery', -- delivery / pickup
  payment_method text not null default 'cash_on_delivery', -- كاش عند الاستلام
  status text not null default 'جديد', -- جديد, قيد التجهيز, في الطريق, تم التسليم
  subtotal_sdg numeric(12,2) not null default 0.00,
  delivery_fee_sdg numeric(12,2) not null default 0.00,
  total_sdg numeric(12,2) not null default 0.00,
  usd_rate_at_purchase numeric(12,2) not null default 3000.00,
  created_at timestamptz default now()
);

-- Order Items Table
create table if not exists public.tarag4_order_items (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  order_id uuid not null references public.tarag4_orders(id) on delete cascade,
  product_id uuid references public.tarag4_products(id) on delete set null,
  product_name text not null,
  quantity integer not null default 1,
  unit_price_usd numeric(10,2) not null default 0.00,
  unit_price_sdg numeric(12,2) not null default 0.00,
  total_price_sdg numeric(12,2) not null default 0.00,
  created_at timestamptz default now()
);

-- Supplier Purchases Table (Admin only)
create table if not exists public.tarag4_purchases (
  id uuid primary key default gen_random_uuid(),
  supplier_name text not null,
  purchase_date date not null default current_date,
  amount_sdg numeric(12,2) not null default 0.00,
  amount_usd numeric(10,2) default 0.00,
  payment_status text not null default 'مدفوع', -- مدفوع / آجل
  invoice_image_url text,
  notes text,
  created_at timestamptz default now()
);

