-- ROW LEVEL SECURITY (RLS) POLICIES
--------------------------------------------------------------------------------

-- Enable RLS on all tables
alter table public.tarag4_settings enable row level security;
alter table public.tarag4_delivery_areas enable row level security;
alter table public.tarag4_products enable row level security;
alter table public.tarag4_customers enable row level security;
alter table public.tarag4_orders enable row level security;
alter table public.tarag4_order_items enable row level security;
alter table public.tarag4_purchases enable row level security;

-- 1. tarag4_settings RLS
drop policy if exists tarag4_settings_select on public.tarag4_settings;
create policy tarag4_settings_select on public.tarag4_settings
  for select to authenticated using (true);

drop policy if exists tarag4_settings_admin_all on public.tarag4_settings;
create policy tarag4_settings_admin_all on public.tarag4_settings
  for all to authenticated
  using (public.tarag4_is_admin())
  with check (public.tarag4_is_admin());

